// src/pages/NotFound.jsx
import React from "react";
import { Link } from "react-router-dom";
import { Helmet } from "react-helmet-async";

const NotFound = () => {
  return (
    <>
      <Helmet>
        <title>404 - Page Not Found | Dishant Gandhi</title>
        <meta
          name="description"
          content="Oops! The page you’re looking for doesn’t exist. Go back to Dishant Gandhi’s homepage or explore latest blogs."
        />
        <link rel="canonical" href="https://dishantg.com/404" />
      </Helmet>

      <section className="min-h-screen flex flex-col items-center justify-center bg-cream px-6 py-16 text-center">
        {/* Decorative circle */}
        <div className="relative mb-8">
          <div className="absolute inset-0 bg-teal-100 rounded-full blur-2xl opacity-40 animate-pulse"></div>
          <div className="relative bg-white border border-gray-200 shadow-lg rounded-full h-40 w-40 flex items-center justify-center">
            <span className="text-6xl font-extrabold text-teal-600">404</span>
          </div>
        </div>

        <h1 className="text-3xl md:text-4xl font-bold text-gray-900 mb-4">
          Oops! Page Not Found
        </h1>
        <p className="text-gray-600 text-base md:text-lg max-w-md mb-8">
          It seems the page you’re looking for has moved or doesn’t exist. You can
          go back to the home page or check out the latest blogs.
        </p>

        <div className="flex flex-wrap gap-4 justify-center">
          <Link
            to="/"
            className="px-6 py-3 rounded-full bg-teal-600 hover:bg-teal-700 text-white font-medium shadow-md transition-all duration-300"
          >
            ← Back to Home
          </Link>
          <Link
            to="/blogs"
            className="px-6 py-3 rounded-full bg-white hover:bg-gray-100 text-teal-700 border border-gray-200 font-medium shadow-sm transition-all duration-300"
          >
            Explore Blogs →
          </Link>
        </div>

        {/* Footer note */}
        <div className="mt-12 text-sm text-gray-400">
          © {new Date().getFullYear()} Dishant Gandhi
        </div>
      </section>
    </>
  );
};

export default NotFound;
