// src/utils/blogFetchers.js

// Fetch from your CMS
const isSnap = typeof navigator !== "undefined" && navigator.userAgent === "ReactSnap";
const isPrerender = typeof window === "undefined" || navigator.userAgent.includes("Prerender");

export async function fetchCmsBlogs() {

    const CMS_URL = "https://cms.dishantshomelab.xyz/items/blogs";
    if (isSnap) {
        console.log("⚠️  Skipping CMS fetch while prerendering");
        return [];
    }

    try {
        if (isPrerender) {
            console.warn("⚠️ Skipping CMS fetch during prerender");
            return [];
        }
        const res = await fetch(CMS_URL, {
            headers: { Accept: "application/json" },
            next: { revalidate: 60 }, // optional (for Next.js caching)
        });

        if (!res.ok) {
            throw new Error(`CMS error ${res.status}`);
        }

        const payload = await res.json();
        const list = Array.isArray(payload?.data) ? payload.data : [];

        return list
            .filter(item => item.type === "ready")
            .map(item => ({
                type: "article",
                source: "cms",
                local: true,
                url: `/blogs/${item.slug}`,
                title: item.title,
                subtitle: item.subtitle,
                excerpt: item.excerpt || (item.content ? String(item.content).replace(/<[^>]+>/g, "").slice(0, 180) : ""),
                image: item.image ? `https://cms.dishantshomelab.xyz/assets/${item.image}?width=1200&quality=80&format=webp` : null,
                created_at: item.date_created || item.created_at || item.date || item.published_at,
                tags: item.tags || [],
                content: item.content,
                slug: item.slug,
                meta: {
                    title: item.meta_title || item.title,
                    description: item.meta_description || item.subtitle || "",
                    canonical: item.canonical_url,
                    keywords: item.keywords,
                },
            }))
            .filter(x => x.title);
    } catch (error) {
        console.error("❌ Failed to fetch CMS blogs:", error);
        return [];
    }
}

// Fetch from Medium RSS
export async function fetchMediumBlogs() {
    const RSS_URL = 'https://medium.com/feed/@dishant_gandhi';
    const API_URL = `https://api.rss2json.com/v1/api.json?rss_url=${encodeURIComponent(RSS_URL)}`;

    if (isSnap) {
        console.log("⚠️  Skipping Medium blogs while prerendering");
        return [];
    }

    try {
        const res = await fetch(API_URL);
        if (!res.ok) throw new Error(`Medium RSS error ${res.status}`);
        const data = await res.json();

        if (data.status !== 'ok') throw new Error('RSS feed error');

        return data.items.map(item => {
            // Extract first image from content if available
            const imgMatch = item.content?.match(/<img[^>]+src="([^">]+)"/);
            const image = imgMatch ? imgMatch[1] : item.thumbnail;

            // Clean HTML from description
            const excerpt = item.description?.replace(/<[^>]+>/g, '').slice(0, 180) || '';

            // Extract slug from URL
            const urlParts = item.link.split('/');
            const slug = urlParts[urlParts.length - 1] || urlParts[urlParts.length - 2];

            return {
                type: "article",
                source: "medium",
                local: false,
                external: true,
                url: item.link, // Original Medium URL
                title: item.title,
                subtitle: "",
                excerpt: excerpt,
                image: image,
                created_at: item.pubDate,
                tags: item.categories || [],
                content: item.content,
                author: item.author,
                slug: slug,
            };
        }).filter(x => x.title);
    } catch (error) {
        console.error('Failed to fetch Medium blogs:', error);
        return [];
    }
}

