// Combine all sources
export async function fetchAllBlogs() {
    const [cmsBlogs, mediumBlogs, externalBlogs] = await Promise.all([
        fetchCmsBlogs(),
        fetchMediumBlogs(),
        fetchExternalBlogs(),
    ]);

    const allBlogs = [...cmsBlogs, ...mediumBlogs, ...externalBlogs];

    // Sort by date (newest first)
    allBlogs.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));

    return allBlogs;
}
