import React, { useEffect, useState, useRef } from "react";
import { RoughNotation } from "react-rough-notation";
import {
  Mail,
  MapPin,
  Calendar,
  ChevronDown,
  Clock,
  MessageSquare,
  Mic,
  Users,
  PenTool,
} from "lucide-react";
import { FaLinkedinIn, FaGithub, FaMediumM } from "react-icons/fa";
import { FaXTwitter } from "react-icons/fa6";

// === CONFIG — update these with your actual IDs/URLs ===
const TALLY_FORM_ID = "NpBovj"; // e.g. "wAxBpY"
const TOPMATE_URL = "https://topmate.io/dishantg"; // your Topmate profile

// === SOCIAL LINKS ===
const socialLinks = [
  {
    name: "LinkedIn",
    url: "https://linkedin.com/in/dishant-gandhi",
    icon: FaLinkedinIn,
    hoverColor: "hover:text-[#0A66C2]",
  },
  {
    name: "GitHub",
    url: "https://github.com/horizon733",
    icon: FaGithub,
    hoverColor: "hover:text-[#333]",
  },
  {
    name: "Twitter",
    url: "https://twitter.com/gandhi_dishant",
    icon: FaXTwitter,
    hoverColor: "hover:text-[#1DA1F2]",
  },
  {
    name: "Medium",
    url: "https://medium.com/@dishant_gandhi",
    icon: FaMediumM,
    hoverColor: "hover:text-[#000]",
  },
];

// === TOPMATE SERVICES ===
const topmateServices = [
  {
    title: "1:1 AI/ML Mentoring",
    duration: "30 min",
    icon: Users,
    color: "bg-teal-500",
  },
  {
    title: "Mock Interview Prep",
    duration: "45 min",
    icon: MessageSquare,
    color: "bg-orange-400",
  },
  {
    title: "RAG / Agentic AI Consult",
    duration: "60 min",
    icon: Clock,
    color: "bg-purple-400",
  },
  {
    title: "Speaking Inquiry",
    duration: "15 min · Free",
    icon: Mic,
    color: "bg-blue-400",
  },
  {
    title: "Career Guidance",
    duration: "30 min",
    icon: PenTool,
    color: "bg-yellow-500",
  },
];

// === FAQ DATA ===
const faqs = [
  {
    question: "What's your typical response time?",
    answer:
      "I usually respond within 24–48 hours during weekdays. For urgent matters, mention it in your subject line.",
  },
  {
    question: "Are you open to podcast or interview appearances?",
    answer:
      "Yes! I enjoy discussing AI trends, chatbot development, and technical education. Send me the format and topics you'd like to cover.",
  },
  {
    question: "Do you mentor developers?",
    answer:
      "Absolutely — I've mentored 4000+ students so far. Book a session on Topmate for structured 1:1 mentoring, or reach out through the form for longer-term arrangements.",
  },
  {
    question: "Can you speak at my event or workshop?",
    answer:
      "I'd love to! I've done 30+ sessions across IIT Guwahati, GDG, MongoDB, Kong, and CNCF meetups. Send me the event details, date, and topic — or book a free 15-min speaking inquiry call on Topmate.",
  },
  {
    question: "Do you write guest posts or contribute articles?",
    answer:
      "Yes — I write on Medium and contribute to tech publications. If you have an interesting platform or topic, let's discuss.",
  },
];

// === FAQ ITEM ===
const FaqItem = ({ question, answer }) => (
  <details className="bg-white rounded-2xl ring-1 ring-gray-200 shadow-sm group">
    <summary className="p-5 sm:p-6 font-semibold text-[#2C2C2A] cursor-pointer list-none flex justify-between items-center gap-4 text-sm sm:text-base">
      <span>{question}</span>
      <ChevronDown
        size={18}
        className="flex-shrink-0 text-teal-600 group-open:rotate-180 transition-transform duration-200"
      />
    </summary>
    <p className="px-5 sm:px-6 pb-5 sm:pb-6 text-sm text-gray-600 leading-relaxed">
      {answer}
    </p>
  </details>
);

// === MAIN COMPONENT ===
const Contact = () => {
  const [faqAnnotationShow, setFaqAnnotationShow] = useState(false);
  const tallyContainerRef = useRef(null);

  // Load Tally embed script
  useEffect(() => {
    const existingScript = document.querySelector(
      'script[src="https://tally.so/widgets/embed.js"]'
    );
    if (!existingScript) {
      const script = document.createElement("script");
      script.src = "https://tally.so/widgets/embed.js";
      script.async = true;
      document.head.appendChild(script);
    }
  }, []);

  // Watch for Tally iframe resize, then re-trigger FAQ annotation
  useEffect(() => {
    const container = tallyContainerRef.current;
    if (!container) return;

    const observer = new ResizeObserver(() => {
      // Toggle off then on to force RoughNotation to recalculate position
      setFaqAnnotationShow(false);
      requestAnimationFrame(() => {
        setFaqAnnotationShow(true);
      });
    });

    observer.observe(container);

    // Also trigger on initial load after a delay
    const timer = setTimeout(() => setFaqAnnotationShow(true), 800);

    return () => {
      observer.disconnect();
      clearTimeout(timer);
    };
  }, []);

  return (
    <section className="bg-[#F5F4EF] pt-24 sm:pt-32 pb-16 sm:pb-24 relative overflow-hidden min-h-screen">
      {/* Grid background */}
      <div className="absolute inset-0 pointer-events-none opacity-40">
        <div
          className="absolute inset-0"
          style={{
            backgroundImage:
              "linear-gradient(#E0DED8 1px, transparent 1px), linear-gradient(90deg, #E0DED8 1px, transparent 1px)",
            backgroundSize: "40px 40px",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse 70% 70% at 50% 50%, transparent -50%, #F5F4EF 100%)",
          }}
        />
      </div>

      <div className="relative z-10 container mx-auto px-4 sm:px-6 lg:px-8 max-w-6xl">
        {/* Header */}
        <div className="text-center mb-12 sm:mb-16">
          <h1 className="text-3xl sm:text-4xl md:text-5xl font-bold text-[#2C2C2A] mb-3">
            Let's{" "}
            <RoughNotation
              type="underline"
              show={true}
              color="#1aacb0"
              strokeWidth={3}
              padding={2}
              animationDuration={800}
            >
              Connect
            </RoughNotation>
          </h1>
          <p className="text-sm sm:text-base text-gray-600 max-w-xl mx-auto">
            Have a project in mind, want me at your event, or just want to
            talk AI? Pick what works for you.
          </p>
        </div>

        {/* Two-column: Form + Sidebar */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-16">
          {/* Left: Tally form embed */}
          <div className="lg:col-span-2" ref={tallyContainerRef}>
            <div className="bg-white rounded-2xl ring-1 ring-gray-200 shadow-sm p-6 sm:p-8">
              <h2 className="text-xl sm:text-2xl font-bold text-[#2C2C2A] mb-2">
                Send a message
              </h2>
              <p className="text-sm text-gray-500 mb-6">
                I'll get back to you within 24–48 hours.
              </p>

              {/* Tally iframe embed */}

              <iframe
                data-tally-src={`https://tally.so/embed/${TALLY_FORM_ID}?alignLeft=1&hideTitle=1&transparentBackground=1&dynamicHeight=1`}
                loading="lazy"
                width="100%"
                height="400"
                frameBorder="0"
                marginHeight="0"
                marginWidth="0"
                title="Contact Form"
                style={{ border: "none", minHeight: "400px" }}
              ></iframe>
            </div>
          </div>

          {/* Right: Info + Book a Session */}
          <div className="space-y-6">
            {/* Book a Session card */}
            <div className="bg-white rounded-2xl ring-1 ring-gray-200 shadow-sm p-6">
              <h3 className="text-sm font-bold text-[#2C2C2A] uppercase tracking-wider mb-1">
                Prefer a call?
              </h3>
              <p className="text-xs text-gray-500 mb-5">
                Book a session on Topmate
              </p>

              <div className="space-y-3 mb-5">
                {topmateServices.map((service) => {
                  const Icon = service.icon;
                  return (
                    <div
                      key={service.title}
                      className="flex items-center gap-3"
                    >
                      <div
                        className={`${service.color} flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-white`}
                      >
                        <Icon size={14} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold text-[#2C2C2A] truncate">
                          {service.title}
                        </p>
                        <p className="text-xs text-gray-500">
                          {service.duration}
                        </p>
                      </div>
                    </div>
                  );
                })}
              </div>

              <a
                href={TOPMATE_URL}
                target="_blank"
                rel="noopener noreferrer"
                className="block w-full text-center bg-[#2C2C2A] hover:bg-[#1a1a18] text-white font-semibold text-sm py-3 px-4 rounded-xl transition-colors"
              >
                Book on Topmate →
              </a>
            </div>

          </div>
        </div>

        {/* FAQ Section */}
        <div className="max-w-3xl mx-auto">
          <div className="text-center mb-8">
            <h2 className="text-2xl sm:text-3xl font-bold text-[#2C2C2A] mb-2">
              Frequently{" "}
              <RoughNotation
                type="underline"
                show={faqAnnotationShow}
                color="#1aacb0"
                strokeWidth={3}
                padding={2}
                animationDuration={800}
              >
                Asked
              </RoughNotation>
            </h2>
          </div>
          <div className="space-y-3">
            {faqs.map((faq) => (
              <FaqItem
                key={faq.question}
                question={faq.question}
                answer={faq.answer}
              />
            ))}
          </div>
        </div>
      </div>
    </section>
  );
};

export default Contact;