import React, { useState, useEffect } from "react";
import {
  Briefcase,
  GraduationCap,
  Hammer,
  HeartHandshake,
  Sparkles,
  Presentation,
  BookOpen,
  Award,
} from "lucide-react";
import { RoughNotation, RoughNotationGroup } from "react-rough-notation";

// === COLOR PALETTE (cycled per item) ===
const COLOR_PALETTE = [
  { color: "bg-teal-500", textColor: "text-teal-600", ringColor: "ring-teal-200" },
  { color: "bg-orange-400", textColor: "text-orange-600", ringColor: "ring-orange-200" },
  { color: "bg-purple-400", textColor: "text-purple-600", ringColor: "ring-purple-200" },
  { color: "bg-blue-400", textColor: "text-blue-600", ringColor: "ring-blue-200" },
  { color: "bg-green-400", textColor: "text-green-600", ringColor: "ring-green-200" },
  { color: "bg-red-400", textColor: "text-red-600", ringColor: "ring-red-200" },
  { color: "bg-yellow-500", textColor: "text-yellow-600", ringColor: "ring-yellow-200" },
  { color: "bg-indigo-400", textColor: "text-indigo-600", ringColor: "ring-indigo-200" },
];

// === DATE FORMATTING ===
const formatDuration = (start, end, ongoing) => {
  const fmt = (iso) => {
    if (!iso) return null;
    const d = new Date(iso);
    return d.toLocaleDateString("en-US", { month: "short", year: "numeric" });
  };
  const startStr = fmt(start);
  const endStr = ongoing ? "Present" : fmt(end);
  if (!startStr && !endStr) return "";
  if (!startStr) return endStr;
  if (!endStr) return startStr;
  return `${startStr} – ${endStr}`;
};

// === API → COMPONENT TRANSFORMER ===
const transformExperienceItem = (item, index) => {
  const palette = COLOR_PALETTE[index % COLOR_PALETTE.length];
  return {
    kind: "work",
    company: item.Company,
    role: item.Role,
    duration: formatDuration(item.start_date, item.end_date, item.on_going),
    description: item.description || "",
    type: item.role_type || "Full-time",
    isCurrent: item.on_going === true,
    tech: item.tech_tools || [],
    metrics: item.metrics || [],
    location: item.location || null,
    ...palette,
  };
};

// === HARDCODED EDUCATION + CERTIFICATIONS ===
const educationEntries = [
  {
    kind: "education",
    company: "Manipal University Jaipur",
    role: "Master of Computer Application in Artificial Intelligence",
    duration: "Aug 2024 – Present",
    description:
      "Pursuing MCA with specialization in Artificial Intelligence — coursework covers advanced machine learning, deep learning, natural language processing, and AI system design.",
    color: "bg-teal-500",
    textColor: "text-teal-600",
    ringColor: "ring-teal-200",
    type: "Education",
    isCurrent: true,
    tech: ["Machine Learning", "Deep Learning", "NLP", "AI System Design"],
    metrics: [],
    location: "Remote, India",
  },
  {
    kind: "education",
    company: "University of Mumbai",
    role: "Bachelor of Science in Information Technology",
    duration: "Jun 2018 – May 2021",
    description:
      "Completed B.Sc. IT with foundational coursework in programming, databases, networking, and web technologies — establishing the technical groundwork for transitioning into AI/ML engineering.",
    color: "bg-purple-400",
    textColor: "text-purple-600",
    ringColor: "ring-purple-200",
    type: "Education",
    isCurrent: false,
    tech: ["Programming", "Databases", "Networking", "Web Technologies"],
    metrics: [{ value: "9.22", label: "CGPI / 10" }],
    location: "Mumbai, India",
  },
  {
    kind: "certification",
    company: "Google",
    role: "Gemini Certified Educator",
    duration: "Certification",
    description:
      "Certified by Google as a Gemini Educator — recognized for proficiency in using Google's Gemini AI tools for educational and instructional contexts.",
    color: "bg-blue-400",
    textColor: "text-blue-600",
    ringColor: "ring-blue-200",
    type: "Certification",
    isCurrent: false,
    tech: ["Gemini", "Google AI", "AI Education"],
    metrics: [],
  },
  {
    kind: "certification",
    company: "DeepLearning.AI",
    role: "Natural Language Processing Specialization",
    duration: "Coursera",
    description:
      "Five-course specialization covering classification and vector spaces, probabilistic models, sequence models, and attention models. Built sentiment analysis, machine translation, and chatbot systems as part of the program.",
    color: "bg-orange-400",
    textColor: "text-orange-600",
    ringColor: "ring-orange-200",
    type: "Certification",
    isCurrent: false,
    tech: ["NLP", "Deep Learning", "Sequence Models", "Attention Mechanisms", "TensorFlow"],
    metrics: [],
  },
  {
    kind: "certification",
    company: "Udacity",
    role: "Intro to Machine Learning",
    duration: "Certification",
    description:
      "Foundational program covering supervised and unsupervised learning algorithms, model evaluation, and the end-to-end ML workflow.",
    color: "bg-green-400",
    textColor: "text-green-600",
    ringColor: "ring-green-200",
    type: "Certification",
    isCurrent: false,
    tech: ["Machine Learning", "Scikit-learn", "Python"],
    metrics: [],
  },
];

// === FILTERS ===
const FILTERS = ["All", "Current", "Full-time", "Internship", "Education", "Certification", "Other"];
const OTHER_TYPES = ["Freelance", "Volunteer", "Trainer", "Contractor"];

// === TYPE → ICON MAPPING ===
const typeIcons = {
  "Full-time": Briefcase,
  Internship: GraduationCap,
  Freelance: Hammer,
  Volunteer: HeartHandshake,
  Trainer: Presentation,
  Contractor: Hammer,
  Education: BookOpen,
  Certification: Award,
};

// === HELPERS ===
const getMonogram = (company) => company.charAt(0).toUpperCase();

const matchesFilter = (entry, filter) => {
  if (filter === "All") return true;
  if (filter === "Current") return entry.isCurrent;
  if (filter === "Education") return entry.kind === "education";
  if (filter === "Certification") return entry.kind === "certification";
  if (filter === "Other") return OTHER_TYPES.includes(entry.type);
  return entry.type === filter;
};

// === SIDEBAR ITEM ===
const SidebarItem = ({ entry, isActive, onClick }) => {
  const TypeIcon = typeIcons[entry.type] || Sparkles;

  return (
    <button
      onClick={onClick}
      className={`w-full text-left flex items-start gap-3 p-3 rounded-lg transition-all duration-200 ${
        isActive ? "bg-white shadow-sm ring-1 ring-gray-200" : "hover:bg-white/50"
      }`}
    >
      <div
        className={`flex-shrink-0 w-10 h-10 rounded-full ${entry.color} ring-2 ring-white shadow-sm flex items-center justify-center text-white font-bold text-sm`}
      >
        {getMonogram(entry.company)}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 mb-0.5">
          <p className="text-sm font-semibold text-[#2C2C2A] truncate">{entry.company}</p>
          {entry.isCurrent && (
            <span className="flex-shrink-0 flex items-center gap-1 text-[10px] font-medium text-teal-700 bg-teal-50 px-1.5 py-0.5 rounded-full">
              <span className="w-1.5 h-1.5 rounded-full bg-teal-500 animate-pulse" />
              Now
            </span>
          )}
        </div>
        <div className="flex items-center gap-1.5 text-xs text-gray-500">
          <TypeIcon size={11} className="flex-shrink-0" />
          <span className="truncate">{entry.duration}</span>
        </div>
      </div>
    </button>
  );
};

// === DESCRIPTION RENDERER ===
// Handles both plain text and bullet-style content from CMS
const renderDescription = (text) => {
  if (!text) return null;
  // Split on newlines, treat lines starting with "-" as bullets
  const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
  const allBullets = lines.every((l) => l.startsWith("-"));

  if (allBullets && lines.length > 1) {
    return (
      <ul className="list-disc list-outside pl-5 space-y-2 text-sm sm:text-base text-gray-700 leading-relaxed">
        {lines.map((line, i) => (
          <li key={i}>{line.replace(/^-\s*/, "")}</li>
        ))}
      </ul>
    );
  }
  return (
    <p className="text-sm sm:text-base text-gray-700 leading-relaxed">
      {lines.join(" ")}
    </p>
  );
};

// === DETAIL PANEL ===
const DetailPanel = ({ entry }) => {
  const TypeIcon = typeIcons[entry.type] || Sparkles;

  return (
    <div className="p-6 sm:p-8">
      {/* Header */}
      <div className="flex items-start gap-4 mb-6">
        <div
          className={`flex-shrink-0 w-16 h-16 rounded-full ${entry.color} ring-4 ring-white shadow-md flex items-center justify-center text-white font-bold text-2xl`}
        >
          {getMonogram(entry.company)}
        </div>
        <div className="flex-1">
          <div className="flex flex-wrap items-center gap-2 mb-1">
            <h3 className="text-xl sm:text-2xl font-bold text-[#2C2C2A]">{entry.company}</h3>
            {entry.isCurrent && (
              <RoughNotation
                type="circle"
                show={true}
                color="#1aacb0"
                strokeWidth={2}
                padding={[4, 8]}
                animationDuration={600}
                iterations={2}
              >
                <span className="text-xs font-semibold text-teal-700 px-1">Current</span>
              </RoughNotation>
            )}
          </div>
          <p className={`text-base sm:text-lg font-semibold ${entry.textColor} mb-1`}>{entry.role}</p>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-gray-500">
            <span>{entry.duration}</span>
            <span className="text-gray-300">·</span>
            <span className="flex items-center gap-1">
              <TypeIcon size={14} />
              {entry.type}
            </span>
            {entry.location && (
              <>
                <span className="text-gray-300">·</span>
                <span>{entry.location}</span>
              </>
            )}
          </div>
        </div>
      </div>

      {/* Description */}
      <div className="mb-6">{renderDescription(entry.description)}</div>

      {/* Metrics */}
      {entry.metrics.length > 0 && (
        <div className="flex flex-wrap gap-3 mb-6">
          {entry.metrics.map((metric, i) => (
            <div
              key={i}
              className={`bg-white ring-1 ${entry.ringColor} rounded-lg px-4 py-3 shadow-sm`}
            >
              <p className={`text-2xl font-bold ${entry.textColor} leading-none`}>{metric.value}</p>
              <p className="text-xs text-gray-500 mt-1">{metric.label}</p>
            </div>
          ))}
        </div>
      )}

      {/* Tech stack */}
      {entry.tech.length > 0 && (
        <div>
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wider mb-2">
            {entry.kind === "work" ? "Tech & Tools" : "Topics Covered"}
          </p>
          <div className="flex flex-wrap gap-2">
            {entry.tech.map((t) => (
              <span
                key={t}
                className="text-xs font-medium text-[#2C2C2A] bg-white ring-1 ring-gray-200 rounded-full px-3 py-1 hover:ring-gray-400 transition-all"
              >
                {t}
              </span>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

// === MAIN COMPONENT ===
const Journey = () => {
  const [activeFilter, setActiveFilter] = useState("All");
  const [activeIndex, setActiveIndex] = useState(0);
  const [workEntries, setWorkEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchExperience = async () => {
      try {
        setLoading(true);
        const response = await fetch(
          "https://cms.dishantshomelab.xyz/items/Experience?sort=-end_date"
        );
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const result = await response.json();
        const transformed = (result.data || []).map(transformExperienceItem);
        setWorkEntries(transformed);
        setError(null);
      } catch (err) {
        console.error("Failed to fetch experience:", err);
        setError("Failed to load experience");
      } finally {
        setLoading(false);
      }
    };
    fetchExperience();
  }, []);

  // Combine fetched work entries + hardcoded education
  const journey = [...workEntries, ...educationEntries];
  const filtered = journey.filter((entry) => matchesFilter(entry, activeFilter));
  const activeEntry = filtered.find((_, i) => i === activeIndex) || filtered[0] || null;

  const handleFilterChange = (filter) => {
    setActiveFilter(filter);
    setActiveIndex(0);
  };

  return (
    <section id="journey" className="bg-[#F5F4EF] py-2 sm:py- relative overflow-hidden">
      {/* Subtle grid background to match hero */}
      <div className="absolute inset-0 pointer-events-none opacity-40">
        <div
          className="absolute inset-0"
          style={{
            backgroundImage:
              "linear-gradient(#E0DED8 1px, transparent 1px), linear-gradient(90deg, #E0DED8 1px, transparent 1px)",
            backgroundSize: "40px 40px",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background: "radial-gradient(ellipse 70% 70% at 50% 50%, transparent -50%, #F5F4EF 100%)",
          }}
        />
      </div>

      <div className="relative z-10 container mx-auto px-4 sm:px-6 lg:px-8 max-w-6xl">
        {/* Section header */}
        <div className="text-center mb-10 sm:mb-14">
          <RoughNotationGroup show={true}>
            <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-[#2C2C2A] mb-3">
              My{" "}
              <RoughNotation type="underline" color="#1aacb0" strokeWidth={3} padding={2} animationDuration={800}>
                Journey
              </RoughNotation>
            </h2>
          </RoughNotationGroup>
          <p className="text-sm sm:text-base text-gray-600">
            Roles, degrees, and certifications shaping my path in AI
          </p>
        </div>

        {/* Filter chips */}
        <div className="flex flex-wrap justify-center gap-2 mb-8">
          {FILTERS.map((filter) => {
            const isActive = activeFilter === filter;
            const count =
              filter === "All"
                ? journey.length
                : journey.filter((e) => matchesFilter(e, filter)).length;

            if (count === 0) return null;

            return (
              <button
                key={filter}
                onClick={() => handleFilterChange(filter)}
                className={`text-xs sm:text-sm font-semibold px-4 py-2 rounded-full transition-all duration-200 ${
                  isActive
                    ? "bg-[#2C2C2A] text-white shadow-md"
                    : "bg-white text-gray-600 hover:bg-gray-50 ring-1 ring-gray-200"
                }`}
              >
                {filter}
                <span className={`ml-1.5 text-[10px] ${isActive ? "text-white/70" : "text-gray-400"}`}>
                  {count}
                </span>
              </button>
            );
          })}
        </div>

        {/* Main content */}
        <div className="bg-[#FAFAF5] rounded-2xl ring-1 ring-gray-200 shadow-sm overflow-hidden">
          {loading ? (
            <div className="p-12 text-center text-gray-500 text-sm">Loading journey…</div>
          ) : error ? (
            <div className="p-12 text-center text-red-500 text-sm">{error}</div>
          ) : journey.length === 0 ? (
            <div className="p-12 text-center text-gray-500 text-sm">No entries found.</div>
          ) : (
            <div className="flex flex-col md:flex-row">
              {/* Sidebar */}
              <div className="md:w-[280px] md:flex-shrink-0 p-3 md:border-r md:border-gray-200 md:max-h-[640px] md:overflow-y-auto">
                {filtered.length === 0 ? (
                  <p className="text-sm text-gray-500 text-center py-8">Nothing matches this filter.</p>
                ) : (
                  <div className="space-y-1">
                    {filtered.map((entry, i) => (
                      <SidebarItem
                        key={entry.company + entry.duration}
                        entry={entry}
                        isActive={activeEntry === entry}
                        onClick={() => setActiveIndex(i)}
                      />
                    ))}
                  </div>
                )}
              </div>

              {/* Detail panel */}
              <div className="flex-1 bg-white">
                {activeEntry ? <DetailPanel entry={activeEntry} /> : null}
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
};

export default Journey;