import { RoughNotation, RoughNotationGroup } from "react-rough-notation";
import {
  Brain,
  Code2,
  Users,
  GraduationCap,
  Sparkles,
  Compass,
  Mail,
} from "lucide-react";

// === TOOLKIT DATA ===
const toolkitCategories = [
  {
    title: "AI",
    icon: Brain,
    color: "bg-teal-500",
    textColor: "text-teal-600",
    ringColor: "ring-teal-200",
    skills: [
      "LLMs",
      "RAG",
      "Agentic AI",
      "LangChain",
      "CrewAI",
      "Pydantic AI",
      "Ollama",
      "OpenAI",
      "HuggingFace",
      "NLP",
      "Rasa",
      "TensorFlow",
      "PyTorch",
    ],
  },
  {
    title: "Development",
    icon: Code2,
    color: "bg-orange-400",
    textColor: "text-orange-600",
    ringColor: "ring-orange-200",
    skills: [
      "Python",
      "FastAPI",
      "React.js",
      "Streamlit",
      "Linux",
      "Docker",
      "Kubernetes",
      "AWS",
      "CI/CD",
      "Neo4j",
      "MongoDB",
      "Qdrant",
      "ChromaDB",
      "Postgres",
    ],
  },
  {
    title: "Leadership",
    icon: Users,
    color: "bg-purple-400",
    textColor: "text-purple-600",
    ringColor: "ring-purple-200",
    skills: [
      "Cross-team Collaboration",
      "Stakeholder Engagement",
      "Scrum & Agile",
      "Community Building",
      "Public Speaking",
      "Technical Writing",
    ],
  },
  {
    title: "Training & Mentoring",
    icon: GraduationCap,
    color: "bg-yellow-500",
    textColor: "text-yellow-600",
    ringColor: "ring-yellow-200",
    skills: [
      "Workshop Design",
      "Developer Onboarding",
      "Hackathon Mentoring",
      "Conference Talks",
      "Hands-on Demos",
      "Open-source Contribution",
    ],
  },
];

// === NOW / NEXT / OPEN TO ===
const statusCards = [
  {
    label: "Now",
    icon: Sparkles,
    color: "bg-teal-500",
    textColor: "text-teal-600",
    content:
      "Architecting RAG and Agentic AI systems end-to-end for US universities at Encoura + RNL — from LLM layer to frontend.",
  },
  {
    label: "Next",
    icon: Compass,
    color: "bg-orange-400",
    textColor: "text-orange-600",
    content:
      "Going deeper into Knowledge Graphs with LLMs (GraphRAG, Neo4j), and shipping more open-source tools and tutorials for the community.",
  },
  {
    label: "Open to",
    icon: Mail,
    color: "bg-purple-400",
    textColor: "text-purple-600",
    content:
      "Fullstack AI consulting, speaking invitations, workshop collaborations, and chats with anyone building real LLM products.",
  },
];

// === TOOLKIT CARD ===
const ToolkitCard = ({ category }) => {
  const Icon = category.icon;
  return (
    <div className="bg-white rounded-2xl p-6 ring-1 ring-gray-200 shadow-sm hover:shadow-md transition-shadow">
      <div className="flex items-center gap-3 mb-4">
        <div
          className={`${category.color} w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-sm`}
        >
          <Icon size={20} />
        </div>
        <h4 className="text-lg font-bold text-[#2C2C2A]">{category.title}</h4>
      </div>
      <div className="flex flex-wrap gap-1.5">
        {category.skills.map((skill) => (
          <span
            key={skill}
            className={`text-xs font-medium text-[#2C2C2A] bg-gray-50 ring-1 ring-gray-200 rounded-full px-2.5 py-1 hover:${category.ringColor} hover:ring-2 transition-all`}
          >
            {skill}
          </span>
        ))}
      </div>
    </div>
  );
};

// === STATUS CARD ===
const StatusCard = ({ status }) => {
  const Icon = status.icon;
  return (
    <div className="flex items-start gap-3 py-4 first:pt-0 last:pb-0 border-b last:border-b-0 border-gray-100">
      <div
        className={`${status.color} flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-white shadow-sm`}
      >
        <Icon size={14} />
      </div>
      <div className="flex-1">
        <p
          className={`text-xs font-bold uppercase tracking-wider ${status.textColor} mb-1`}
        >
          {status.label}
        </p>
        <p className="text-sm text-gray-700 leading-relaxed">{status.content}</p>
      </div>
    </div>
  );
};

// === MAIN COMPONENT ===
const About = () => {
  return (
    <section
      id="about"
      className="bg-[#F5F4EF] py-8 sm:py-15 relative overflow-hidden"
    >
      {/* Subtle grid background to match hero */}
      <div className="absolute inset-0 pointer-events-none opacity-40">
        <div
          className="absolute inset-0"
          style={{
            backgroundImage:
              "linear-gradient(#E0DED8 1px, transparent 1px), linear-gradient(90deg, #E0DED8 1px, transparent 1px)",
            backgroundSize: "40px 40px",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse 70% 70% at 50% 50%, transparent -50%, #F5F4EF 100%)",
          }}
        />
      </div>

      <div className="relative z-10 container mx-auto px-4 sm:px-6 lg:px-8 max-w-6xl">
        {/* Section header */}
        <div className="text-center mb-12 sm:mb-16">
          <h2 className="text-3xl sm:text-4xl md:text-5xl font-bold text-[#2C2C2A] mb-3">
            About{" "}
            <RoughNotation
              type="underline"
              show={true}
              color="#1aacb0"
              strokeWidth={3}
              padding={2}
              animationDuration={800}
            >
              Me
            </RoughNotation>
          </h2>
         <p className="text-sm sm:text-base text-gray-600">
  Fullstack AI developer by day, community builder by everything else
</p>
        </div>

        {/* Top section: Narrative + Status */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-16">
          {/* Narrative — 2 columns */}
          <div className="lg:col-span-2 bg-white rounded-2xl p-8 sm:p-10 ring-1 ring-gray-200 shadow-sm">
            <RoughNotationGroup show={true}>
              <div className="space-y-5 text-[#2C2C2A] leading-relaxed">
                <p className="text-base sm:text-lg">
                  I'm a{" "}
                  <RoughNotation
                    type="highlight"
                    color="#1aacb066"
                    animationDuration={800}
                    padding={[1, 2]}
                  >
                    fullstack AI developer
                  </RoughNotation>
                  — which means I don't just train models or wire up an LLM call and
                  hand it off. I architect the whole thing: the AI layer (agents, RAG,
                  LLM orchestration), the backend services holding it together, and
                  the frontend people actually use. Down to up, end to end.
                </p>

                <p className="text-base sm:text-lg">
                  Most AI work today gets stuck in two places — a notebook that demos
                  well but never ships, or a prototype that ships but nobody knows how
                  to maintain.{" "}
                  <RoughNotation
                    type="underline"
                    color="#1aacb0"
                    strokeWidth={2}
                    animationDuration={800}
                    padding={1}
                  >
                    I work in the messy middle
                  </RoughNotation>
                  , where you have to make real product decisions: which parts the LLM
                  should decide, which parts you constrain, how the data flows, what
                  the user actually sees. That's where the interesting engineering
                  lives.
                </p>

                <p className="text-base sm:text-lg">
                  The other half of what I do is{" "}
                  <RoughNotation
                    type="highlight"
                    color="#FFB85C66"
                    animationDuration={800}
                    padding={[1, 2]}
                  >
                    giving back to the community
                  </RoughNotation>{" "}
                  that taught me everything. I teach workshops, write blogs, record
                  video tutorials, speak at meetups and conferences, and volunteer
                  where I can. Most of what I know I figured out by trying to explain
                  it to someone else — so teaching isn't a side project, it's part of
                  how I learn.
                </p>

                <p className="text-base sm:text-lg">
                  Dishant has run sessions and workshops at{" "}
                  <RoughNotation
                    type="circle"
                    color="#1aacb0"
                    strokeWidth={2}
                    animationDuration={800}
                    padding={[2, 4]}
                    iterations={2}
                  >
                    IIT Guwahati, GDG, MongoDB, Kong, and CNCF meetups
                  </RoughNotation>
                  , and serves as a Young Professional Member for IEEE Region 10. The
                  thread tying it all together: AI is more useful when more people can
                  actually build with it.
                </p>
              </div>
            </RoughNotationGroup>
          </div>

          {/* Status card — 1 column */}
          <div className="bg-white rounded-2xl p-6 sm:p-8 ring-1 ring-gray-200 shadow-sm">
            <h3 className="text-sm font-bold text-[#2C2C2A] uppercase tracking-wider mb-2">
              Status
            </h3>
            <p className="text-xs text-gray-500 mb-6">
              Where my head is at right now
            </p>
            <div className="divide-y divide-gray-100">
              {statusCards.map((status) => (
                <StatusCard key={status.label} status={status} />
              ))}
            </div>
          </div>
        </div>

        {/* Toolkit section header */}
        <div className="text-center mb-8">
          <h3 className="text-2xl sm:text-3xl font-bold text-[#2C2C2A] mb-2">
            My{" "}
            <RoughNotation
              type="underline"
              show={true}
              color="#1aacb0"
              strokeWidth={3}
              padding={2}
              animationDuration={800}
            >
              Toolkit
            </RoughNotation>
          </h3>
          <p className="text-sm text-gray-600">
            What I reach for when shipping real systems
          </p>
        </div>

        {/* Toolkit grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-5">
          {toolkitCategories.map((category) => (
            <ToolkitCard key={category.title} category={category} />
          ))}
        </div>
      </div>
    </section>
  );
};

export default About;