import React, { useState } from "react";
import { HiMenu, HiX } from "react-icons/hi";
import { Link, useLocation } from "react-router-dom";

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const { pathname } = useLocation();

  // Helper: ensure we navigate home before jumping to #speaking if not already on "/"
  const goToSpeaking = (e) => {
    if (pathname !== "/") {
      // Let the browser handle href="/" navigation first, then jump after render
      // Using full anchor with hash works too: href="/#speaking"
      // But to be extra safe across routers, do a programmatic approach:
      e.preventDefault();
      window.location.href = "/#speaking";
    }
    setIsOpen(false);
  };
  const goToHero = (e) => {
    if (pathname !== "/") {
      // Let the browser handle href="/" navigation first, then jump after render
      // Using full anchor with hash works too: href="/#hero"
      // But to be extra safe across routers, do a programmatic approach:
      e.preventDefault();
      window.location.href = "/#hero";
    }
    setIsOpen(false);
  };

  return (
    <nav className="fixed w-full top-0 bg-cream/90 backdrop-blur-sm z-50 border-b border-teal-100">
      <div className="container mx-auto px-3 sm:px-4 py-2 sm:py-3">
        <div className="flex justify-between items-center">
          {/* Logo */}
          <a
            href="/"
            className="text-xl sm:text-2xl lg:text-3xl font-normal text-teal-600 hover:no-underline"
            style={{ fontFamily: "Brittany Signature" }}
            onClick={() => setIsOpen(false)}
          >
            Dishant Gandhi
          </a>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden text-gray-600 hover:text-teal-600 focus:outline-none transition-colors duration-200"
            onClick={() => setIsOpen(!isOpen)}
            aria-label="Toggle menu"
            aria-expanded={isOpen}
          >
            {isOpen ? <HiX className="h-5 w-5 sm:h-6 sm:w-6" /> : <HiMenu className="h-5 w-5 sm:h-6 sm:w-6" />}
          </button>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-4 lg:space-x-8">
            <ul className="flex space-x-4 lg:space-x-8 font-medium text-gray-700">
              <li>
                <a
                  href="/"
                  onClick={goToHero}
                  className="text-darkText hover:text-teal-600 transition-colors hover:no-underline"
                >
                  Home
                </a>
              </li>

              {/* Speaking uses native anchor to avoid router hash issues */}
              <li>
                <a
                  href="/#speaking"
                  onClick={goToSpeaking}
                  className="text-darkText hover:text-teal-600 transition-colors hover:no-underline"
                >
                  Speaking
                </a>
              </li>
              <li>
                <Link
                  to="/blogs"
                  className="text-darkText hover:text-teal-600 transition-colors hover:no-underline"
                >
                  Blogs
                </Link>
              </li>
              <li>
                <Link to="/contact" className="text-darkText hover:text-teal-600 transition-colors hover:no-underline">
                  Contact
                </Link>
              </li>
            </ul>

            {/* NEW: Book a Call — solid button, stands out */}
            {/* <div>
              <a
                href="https://topmate.io/dishantg"
                target="_blank"
                rel="noopener noreferrer"
                className="px-3 py-1.5 sm:px-4 sm:py-2 text-sm sm:text-base border-2 border-black text-black rounded-lg hover:bg-black hover:text-white transition-colors duration-300 hover:no-underline"
              >
                Book a Call
              </a>
              
            </div> */}
            {/* CV Button */}
            <div>
              <a
                href="https://cms.dishantshomelab.xyz/assets/4a176870-7d17-4dcb-bbaa-56a579c0e1d0?download=1"
                download="Dishant_Gandhi_resume.pdf"
                className="px-3 py-1.5 sm:px-4 sm:py-2 text-sm sm:text-base border-2 border-teal-600 text-teal-600 rounded-lg hover:bg-teal-600 hover:text-white transition-colors duration-300 hover:no-underline"
              >
                Download CV
              </a>

            </div>
          </div>
        </div>

        {/* Mobile Menu */}
        <div
          className={`md:hidden transform transition-all duration-300 ease-in-out ${isOpen ? "opacity-100 scale-y-100" : "opacity-0 scale-y-0 h-0"
            }`}
        >
          <ul className="flex flex-col space-y-3 sm:space-y-4 font-medium text-gray-700 pt-4">
            <li>
              <a
                href="/#hero"
                onClick={goToHero}
                className="block text-sm sm:text-base text-darkText hover:text-teal-600 transition-colors hover:no-underline"
              >
                Home
              </a>
            </li>
            <li>
              {/* Native anchor; close menu after click */}
              <a
                href="/#speaking"
                onClick={goToSpeaking}
                className="block text-sm sm:text-base text-darkText hover:text-teal-600 transition-colors hover:no-underline"
              >
                Speaking
              </a>
            </li>
            <li>
              <Link
                to="/blogs"
                onClick={() => setIsOpen(false)}
                className="block text-sm sm:text-base text-darkText hover:text-teal-600 transition-colors hover:no-underline"
              >
                Blogs
              </Link>
            </li>
            <li>
              <Link
                to="/contact"
                onClick={() => setIsOpen(false)}
                className="block text-sm sm:text-base text-darkText hover:text-teal-600 transition-colors hover:no-underline"
              >
                Contact
              </Link>
            </li>
            <li className="pt-2 sm:pt-4">
              {/* NEW: Book a Call — solid button, stands out */}
              {/* <a
                href="https://topmate.io/dishantg"
                target="_blank"
                rel="noopener noreferrer"
                className="inline-block px-3 py-1.5 sm:px-4 sm:py-2 text-sm sm:text-base border-2 border-black text-black rounded-lg hover:bg-black hover:text-white transition-colors duration-300 hover:no-underline"
              >
                Book a Call
              </a> */}
              <a
                href="https://cms.dishantshomelab.xyz/assets/4a176870-7d17-4dcb-bbaa-56a579c0e1d0?download=1"
                download="Dishant_Gandhi_resume.pdf"
                onClick={() => setIsOpen(false)}
                className="inline-block px-3 py-1.5 sm:px-4 sm:py-2 text-sm sm:text-base border-2 border-teal-600 text-teal-600 rounded-lg hover:bg-teal-600 hover:text-white transition-colors duration-300 hover:no-underline"
              >
                Download CV
              </a>
            </li>
          </ul>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
