// App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import { Helmet, HelmetProvider } from "react-helmet-async";
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import NewHero from "./components/NewHero";
import Experience from "./components/Experience";
import Education from "./components/Education";
import Journey from "./components/Journey";
import Speaking from "./components/Speaking";
import Footer from "./components/Contact";
import About from "./components/About";
import Blog from "./pages/Blog";
import BlogPost from "./pages/BlogPost";
import Contact from "./pages/Contact";
import NotFound from "./pages/NotFound";
import ScrollToHash from "./components/ScrollToHash";

const SITE_URL = "https://dishantg.com";
const SITE_TITLE = "Dishant Gandhi | AI & ML Consultant";
const SITE_DESC =
  "Dishant Gandhi — AI/ML Consultant specializing in Generative AI, LLMs, Conversational AI, and Cloud-native architectures. Explore projects, talks, and blogs.";
const SITE_IMAGE = `${SITE_URL}/assets/cover-image.png`; 

const HomePage = () => (
  <>
    {/* <Hero /> */}
    <NewHero />
    <About />
    {/* <Experience />
    <Education /> */}
    <Journey />
    <Speaking />
  </>
);

const App = () => (
  <HelmetProvider>
    <Router>
      {/* ✅ Default Helmet for whole site */}
      <Helmet>
        <title>{SITE_TITLE}</title>
        <meta name="description" content={SITE_DESC} />
        <link rel="canonical" href={SITE_URL} />

        {/* Open Graph / Facebook / WhatsApp / LinkedIn */}
        <meta property="og:type" content="website" />
        <meta property="og:url" content={SITE_URL} />
        <meta property="og:title" content={SITE_TITLE} />
        <meta property="og:description" content={SITE_DESC} />
        <meta property="og:image" content={SITE_IMAGE} />
        <meta property="og:site_name" content="Dishant Gandhi" />

        {/* Twitter / X */}
        <meta name="twitter:card" content="summary_large_image" />
        <meta name="twitter:url" content={SITE_URL} />
        <meta name="twitter:title" content={SITE_TITLE} />
        <meta name="twitter:description" content={SITE_DESC} />
        <meta name="twitter:image" content={SITE_IMAGE} />

        {/* Basic favicon and theme */}
        <link rel="icon" href="/favicon.ico" />
        <meta name="theme-color" content="#14b8a6" />

        {/* Schema / SEO keywords */}
        <meta
          name="keywords"
          content="Dishant Gandhi, Generative AI, LLMs, RAG, Conversational AI, LangChain, Cloud, AI Consultant"
        />
      </Helmet>

      <div>
        <Navbar />
        <ScrollToHash />
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route path="/blogs" element={<Blog />} />
          <Route path="/blogs/:slug" element={<BlogPost />} />
          <Route path="/contact" element={<Contact />} />
          <Route path="*" element={<NotFound />} />
        </Routes>
        <Footer />
      </div>
    </Router>
  </HelmetProvider>
);

export default App;
