import React, { useEffect, useRef, useState } from "react";
import ArrowSVG from "../assets/arrow.svg";
import { RoughNotation } from "react-rough-notation";

const HERO_IMAGE = {
  mobile: "/assets/profile-hero-800.webp",
  desktop: "/assets/profile-hero-1200.webp",
  width: 800,
  height: 1313,
};

const HeroProfileImage = ({ className }) => (
  <picture>
    <source media="(min-width: 1024px)" srcSet={HERO_IMAGE.desktop} type="image/webp" />
    <img
      src={HERO_IMAGE.mobile}
      alt="Dishant Gandhi"
      className={className}
      width={HERO_IMAGE.width}
      height={HERO_IMAGE.height}
      decoding="async"
      fetchPriority="high"
      loading="eager"
    />
  </picture>
);

const roundToNearestTen = (n) => Math.round(n / 10) * 10;const CountUp = ({ end, duration = 2000, suffix = "", start = 0, delay = 0, formatK = false }) => {
  const [count, setCount] = useState(start);
  const rafRef = useRef(null);

  useEffect(() => {
    let startTime = null;
    const timeoutId = setTimeout(() => {
      const step = (timestamp) => {
        if (!startTime) startTime = timestamp;
        const progress = Math.min((timestamp - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3); // easeOutCubic
        const current = Math.floor(start + (end - start) * eased);
        setCount(current);
        if (progress < 1) {
          rafRef.current = requestAnimationFrame(step);
        } else {
          setCount(end);
        }
      };
      rafRef.current = requestAnimationFrame(step);
    }, delay);

    return () => {
      clearTimeout(timeoutId);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [end, duration, start, delay]);

  // Format display value
  const displayValue = formatK && count >= 1000
    ? `${(count / 1000).toFixed(count === end ? 0 : 1)}k`
    : count.toLocaleString();

  return <>{displayValue}{suffix}</>;
};

// === Years of experience from October 2020 ===
const calculateYearsOfExperience = () => {
  const startYear = 2020;
  const startMonth = 9; // October (0-indexed)
  const now = new Date();
  let years = now.getFullYear() - startYear;
  if (now.getMonth() < startMonth) years -= 1;
  return years;
};

const NewHero = () => {
  const heroRef = useRef(null);
  const [show, setShow] = useState(false);
  const [engagementsCount, setEngagementsCount] = useState(null);

  useEffect(() => {
    const timer = setTimeout(() => setShow(true), 600);
    return () => clearTimeout(timer);
  }, []);

  // Count workshops from CMS (exclude "Attended …" entries — not speaking engagements)
  useEffect(() => {
    const fetchEngagementsCount = async () => {
      try {
        const response = await fetch(
          "https://cms.dishantshomelab.xyz/items/workshops?filter[event_name][_ncontains]=Attended&aggregate[count]=id"
        );
        if (!response.ok) return;
        const result = await response.json();
        const count = parseInt(result?.data?.[0]?.count?.id, 10);
        if (!isNaN(count)) setEngagementsCount(roundToNearestTen(count));
      } catch (err) {
        console.error("Failed to fetch engagements count:", err);
      }
    };
    fetchEngagementsCount();
  }, []);

  useEffect(() => {
    const elements = heroRef.current?.querySelectorAll("[data-animate]");
    elements?.forEach((el, i) => {
      el.style.opacity = "0";
      el.style.transform = "translateY(18px)";
      setTimeout(() => {
        el.style.transition = "opacity 0.7s ease, transform 0.7s ease";
        el.style.opacity = "1";
        el.style.transform = "translateY(0)";
      }, i * 120);
    });
  }, []);

  // Stats config — single source of truth
  const yearsOfExperience = calculateYearsOfExperience();
const stats = [
  { end: yearsOfExperience, suffix: "+", label: "Yrs\nExperience"},
  { end: engagementsCount ?? 0, suffix: "+", label: "Talks &\nEngagements", skipUntilLoaded: engagementsCount == null },
  { end: 4000, suffix: "+", label: "Students\nMentored", formatK: true },
];

  // Reusable stats renderer
  const renderStats = (textSizeClass) => (
  <div className="flex gap-3 sm:gap-6 mt-2 sm:mt-3">
    {stats.map(({ end, suffix, label, formatK, skipUntilLoaded }, i) => (
      <div key={label}>
        <p className={`font-bold text-[#2C2C2A] m-0 leading-[1.1] ${textSizeClass}`}>
          {skipUntilLoaded ? (
            <span className="inline-block min-w-[2ch]">&nbsp;</span>
          ) : (
            <CountUp
              end={end}
              suffix={suffix}
              duration={2000}
              delay={800 + i * 150}
              formatK={formatK}
            />
          )}
        </p>
        <p className="text-[10px] sm:text-[11px] text-[#888780] mt-1 leading-[1.4] whitespace-pre-line">
          {label}
        </p>
      </div>
    ))}
  </div>
);

  return (
    <section
      ref={heroRef}
      id="hero"
      className="relative bg-[#F5F4EF] overflow-hidden pb-0"
    >
      {/* Grid background */}
      <div className="absolute inset-0 pointer-events-none">
        <div
          className="absolute inset-0"
          style={{
            backgroundImage:
              "linear-gradient(#E0DED8 1px, transparent 1px), linear-gradient(90deg, #E0DED8 1px, transparent 1px)",
            backgroundSize: "40px 40px",
          }}
        />
        <div
          className="absolute inset-0"
          style={{
            background:
              "radial-gradient(ellipse 70% 70% at 50% 50%, transparent -50%, #F5F4EF 100%)",
          }}
        />
      </div>

      <div className="relative z-10 w-full max-w-7xl mx-auto px-4 sm:px-6 md:px-12 pt-16 sm:pt-20 md:pt-24">
        {/* Big script greeting */}
        <div className="absolute left-0 right-0 top-1/6 flex items-end justify-center mb-0 pointer-events-none select-none" style={{ zIndex: -1 }}>
          <span
            data-animate
            className="block leading-none tracking-[-2px] text-[#1D9E75]"
            style={{ fontFamily: "Brittany Signature", fontSize: "clamp(40px, 10vw, 120px)" }}
          >
            Hey,
          </span>
          <span
            data-animate
            className="block leading-none tracking-[-2px] text-[#0F4060]"
            style={{ fontFamily: "Brittany Signature", fontSize: "clamp(40px, 10vw, 120px)" }}
          >
            There
          </span>
        </div>

        {/* === MOBILE & TABLET LAYOUT === */}
        <div className="lg:hidden flex flex-col pb-0">
          <div className="relative flex items-end gap-4 min-h-[380px] sm:min-h-[440px] md:min-h-[480px]">
            <div data-animate className="w-[52%] sm:w-[55%] md:w-[58%] flex flex-col gap-4 sm:gap-5 md:gap-6 pt-16 sm:pt-25 md:pt-36 pb-20 sm:pb-24 z-10">
              <div>
                <p className="font-bold text-[#2C2C2A] leading-[1.5] m-0 text-[clamp(13px,3vw,18px)]">AI/ML Consultant</p>
                <p className="font-bold text-[#2C2C2A] leading-[1.5] m-0 text-[clamp(13px,3vw,18px)]">| Public Speaker</p>
              </div>

              <div className="w-fit my-1 sm:my-2">
                <RoughNotation type="circle" show={show} color="#1aacb0" strokeWidth={2} padding={[6, 8]} animationDuration={800} iterations={2}>
                  <span className="block font-bold text-[#111111] leading-[1.6] tracking-[0.2px] text-[clamp(9px,2vw,13px)] max-w-[180px]">
                    Transforming Ideas into Intelligent Solutions with AI and Innovation
                  </span>
                </RoughNotation>
              </div>

              {renderStats("text-[clamp(16px,4vw,26px)]")}

              <div className="relative w-fit mt-2 sm:mt-3">
                <div className="absolute top-[4px] left-[4px] w-full h-full rounded-lg border-[1.5px] border-[#2C2C2A] bg-transparent" />
                <div className="relative bg-white border-[1.5px] border-[#2C2C2A] rounded-lg px-3 sm:px-5 py-[8px] sm:py-[10px] text-[11px] sm:text-[13px] font-semibold text-[#2C2C2A] whitespace-nowrap">
                  dishantg.official@gmail.com
                </div>
              </div>
            </div>

            <div className="absolute right-0 bottom-0 w-[50%] sm:w-[55%] md:w-[48%] translate-y-[15%]">
              <HeroProfileImage className="w-full h-auto object-contain" />
            </div>
          </div>
        </div>

        {/* === DESKTOP LAYOUT === */}
        <div className="hidden lg:flex relative flex-row items-end justify-center min-h-[calc(100vh-80px)] max-h-[900px]">
          <div data-animate className="flex-1 flex flex-col justify-end pb-[20vh] gap-6">
            <div>
              <p className="font-bold text-[#2C2C2A] leading-[1.5] m-0 text-[clamp(14px,1.6vw,20px)]">AI/ML Consultant</p>
              <p className="font-bold text-[#2C2C2A] leading-[1.5] m-0 text-[clamp(14px,1.6vw,20px)]">| Public Speaker</p>
            </div>

            <img src={ArrowSVG} alt="" className="w-[15vw] ml-28 h-auto" />

            {renderStats("text-[clamp(20px,2.5vw,30px)]")}
          </div>

          <div className="w-1/2 relative flex items-end justify-center">
            <HeroProfileImage className="mx-auto h-full max-h-[90vh] w-auto object-contain" />
          </div>

          <div data-animate className="flex-1 flex flex-col items-end justify-end pb-[30vh] gap-8">
            <RoughNotation type="circle" show={show} color="#1aacb0" strokeWidth={3} padding={[18, 24]} animationDuration={800} iterations={6}>
              <p className="font-bold text-[#111111] leading-[1.8] tracking-[0.2px] text-[clamp(11px,1vw,14px)]">
                Transforming Ideas into<br />
                Intelligent Solutions with<br />
                AI and Innovation
              </p>
            </RoughNotation>

            <div className="relative">
              <div className="absolute top-[5px] left-[5px] w-full h-full rounded-lg border-[1.5px] border-[#2C2C2A] bg-transparent" />
              <div className="relative bg-white border-[1.5px] border-[#2C2C2A] rounded-lg px-5 py-[10px] text-[13px] font-semibold text-[#2C2C2A] whitespace-nowrap">
                dishantg.official@gmail.com
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default NewHero;