// src/pages/BlogPost.jsx
import React, { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeRaw from "rehype-raw";
import { MdOutlineDateRange } from "react-icons/md";
import { FiClock } from "react-icons/fi";
import { Helmet } from "react-helmet-async";

const CMS_URL = "https://cms.dishantshomelab.xyz/items/blogs";

function mapCmsToCard(item) {
  return {
    slug: item.slug,
    title: item.title,
    subtitle: item.subtitle,
    content: item.content,
    image: item.image
      ? `https://cms.dishantshomelab.xyz/assets/${item.image}`
      : null,
    cover_alt: item.cover_alt || "",
    created_at:
      item.date_created || item.created_at || item.date || item.published_at,
    tags: item.tags || [],
    // Parse author details from CMS
    author: item.author || "Dishant Gandhi",
    author_bio: item.author_bio || "",
    author_avatar: item.author_image
      ? `https://cms.dishantshomelab.xyz/assets/${item.author_image}`
      : "https://cms.dishantshomelab.xyz/assets/7a247151-16ee-4d44-9138-0dcf1e028341",
  };
}

const BlogPost = () => {
  const { slug } = useParams();
  const [blog, setBlog] = useState(null);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    let alive = true;
    (async () => {
      try {
        const res = await fetch(CMS_URL, {
          headers: { Accept: "application/json" },
        });
        const payload = await res.json();
        const list = Array.isArray(payload)
          ? payload
          : Array.isArray(payload?.data)
            ? payload.data
            : null;
        if (!list) throw new Error("No blogs found");
        const found = list.map(mapCmsToCard).find((b) => b.slug === slug);
        if (alive) setBlog(found || null);
      } catch (e) {
        if (alive) setBlog(null);
      } finally {
        if (alive) setLoading(false);
      }
    })();
    return () => {
      alive = false;
    };
  }, [slug]);

  if (loading) {
    return (
      <section className="py-20 px-5 text-center min-h-screen flex items-center justify-center bg-cream">
        <div className="text-lg text-lightText">Loading blog post…</div>
      </section>
    );
  }

  if (!blog) {
    return (
      <section className="py-20 px-5 text-center min-h-screen flex items-center justify-center bg-cream">
        <div className="text-lg text-lightText">Blog post not found</div>
        <button
          className="mt-6 px-6 py-3 bg-teal-600 hover:bg-teal-700 text-white font-medium rounded-lg transition-colors duration-300"
          onClick={() => navigate("/blog")}
        >
          ← Back to Blogs
        </button>
      </section>
    );
  }

  // Prepare meta fields
  const meta = blog.meta || {};
  const metaTitle = meta.title || blog.title;
  const metaDescription = meta.description || blog.subtitle || "";
  const canonicalUrl = meta.canonical || (typeof window !== "undefined" ? window.location.href : "");
  const ogImage = blog.image;
  const keywords = Array.isArray(blog.tags) ? blog.tags.join(", ") : "";

  return (
    <>
      <Helmet>
        <title>{metaTitle}</title>
        {metaDescription && <meta name="description" content={metaDescription} />}
        {canonicalUrl && <link rel="canonical" href={canonicalUrl} />}
        {ogImage && <meta property="og:image" content={ogImage} />}
        <meta property="og:title" content={metaTitle} />
        <meta property="og:description" content={metaDescription} />
        {keywords && <meta name="keywords" content={keywords} />}
        <meta property="og:type" content="article" />
        <meta property="og:url" content={canonicalUrl} />
      </Helmet>
      <section className="min-h-screen w-full bg-white pt-4">
        {/* Gap below navbar */}
        <div className="h-20 md:h-24" />
        <div className="max-w-3xl mx-auto px-4">
          {/* Category pill */}
          <div className="mb-4">
            <span className="inline-block bg-teal-100 text-teal-700 text-xs font-semibold px-3 py-1 rounded-full uppercase tracking-wide">
              {blog?.category || (blog?.tags?.[0] || "General")}
            </span>
          </div>
          {/* Title */}
          <h1 className="text-4xl md:text-5xl font-extrabold text-gray-900 mb-4 leading-tight tracking-tight">
            {blog.title}
          </h1>
          {/* Meta row */}
          <div className="flex items-center gap-3 text-gray-500 text-sm mb-8 flex-wrap">
            {/* Author avatar and name */}
            <img
              src={blog.author_avatar}
              alt={blog.name}
              className="w-12 h-12 rounded-full object-cover border border-gray-200"
            />
            <span className="font-medium">{blog.author}</span>
            <span className="mx-1 text-gray-300">·</span>
            {/* // Date */}
            <span className="flex items-center gap-1">
              <MdOutlineDateRange className="w-4 h-4 inline-block text-gray-400" />
              {blog.created_at && (
                <span>
                  {new Date(blog.created_at).toLocaleDateString(undefined, {
                    year: "numeric",
                    month: "short",
                    day: "numeric",
                  })}
                </span>
              )}
            </span>
            <span className="mx-1 text-gray-300">·</span>
            {/* // Read time */}
            <span className="flex items-center gap-1">
              {/* Use react-icons for clock */}
              <FiClock className="w-4 h-4 inline-block text-gray-400" />
              {Math.max(
                1,
                Math.round(
                  (blog.content ? blog.content.split(/\s+/).length : 0) / 200
                )
              )}{" "}
              min read
            </span>
            <span className="mx-1 text-gray-300">·</span>
          </div>
          {/* Featured image */}
          {blog.image && (
            <img
              src={blog.image}
              alt={blog.cover_alt || blog.title}
              className="w-full h-[400px] object-cover object-center rounded-2xl shadow mb-10"
              style={{ background: "#f8fafc" }}
            />
          )}
          {/* Subtitle */}
          {blog.subtitle && (
            <h2 className="text-xl text-gray-600 mb-8 font-normal leading-relaxed">
              {blog.subtitle}
            </h2>
          )}
        </div>
        {/* Article content */}
        <article className="prose prose-lg md:prose-xl max-w-3xl mx-auto px-4 pb-24 pt-0 prose-img:rounded-xl prose-img:shadow prose-img:my-8 prose-code:bg-gray-100 prose-code:rounded prose-code:px-1 prose-code:py-0.5 prose-pre:bg-gray-900 prose-pre:text-white prose-pre:rounded-lg prose-pre:p-4 prose-pre:overflow-x-auto prose-pre:my-4">
          <ReactMarkdown
            remarkPlugins={[remarkGfm]}
            rehypePlugins={[rehypeRaw]}
            components={{
              h1: ({ node, ...props }) => <h1 className="text-3xl md:text-4xl font-bold mt-8 mb-4" {...props} />,
              h2: ({ node, ...props }) => <h2 className="text-2xl md:text-3xl font-semibold mt-8 mb-4" {...props} />,
              h3: ({ node, ...props }) => <h3 className="text-xl md:text-2xl font-semibold mt-6 mb-3" {...props} />,
              h4: ({ node, ...props }) => <h4 className="text-lg md:text-xl font-semibold mt-5 mb-2" {...props} />,
              p: ({ node, ...props }) => <p className="my-4 leading-relaxed" {...props} />,
              img: ({ node, ...props }) => (
                <img
                  {...props}
                  className="rounded-xl shadow my-8 max-w-full h-auto"
                  loading="lazy"
                />
              ),
              code({ node, inline, className, children, ...props }) {
                const isInline =
                  inline !== undefined
                    ? inline
                    : node?.position?.start?.line === node?.position?.end?.line;
                const lang = (className || "").replace("language-", "");
                if (isInline) {
                  // Inline code: simple highlight, not a block
                  return (
                    <code className="inline bg-gray-100 text-purple-700 px-1 py-0.5 rounded font-mono text-sm whitespace-nowrap"
                      {...props}
                    >
                      {children}
                    </code>
                  );
                }
                const baseBlock =
                  "rounded-lg p-4 overflow-x-auto my-4 font-mono text-sm leading-relaxed";
                if (lang === "text") {
                  // Simple highlight for text code blocks
                  return (
                    <pre style={{
                      background: "#f6f8fa",
                      borderRadius: "6px",
                      padding: "12px",
                      fontFamily: "monospace",
                      fontSize: "95%",
                      color: "#24292f",
                      border: "1px solid #e1e4e8",
                      margin: "1em 0"
                    }}>
                      <code {...props}>{children}</code>
                    </pre>
                  );
                }
                if (lang === "python") {
                  // Python style
                  return (
                    <pre className={`bg-slate-800 text-yellow-200 ${baseBlock}`}>
                      <code {...props}>{children}</code>
                    </pre>
                  );
                }
                if (lang === "bash") {
                  // Bash style
                  return (
                    <pre className={`bg-slate-900 text-green-300 ${baseBlock}`}>
                      <code {...props}>{children}</code>
                    </pre>
                  );
                }
                // Default block code
                return (
                  <pre className={`bg-gray-100 text-gray-800 border border-gray-200 ${baseBlock}`}>
                    <code className={className} {...props}>
                      {children}
                    </code>
                  </pre>
                );
              },
              ul: ({ node, ...props }) => (
                <ul className="list-disc pl-6 my-4" {...props} />
              ),
              ol: ({ node, ...props }) => (
                <ol className="list-decimal pl-6 my-4" {...props} />
              ),
              li: ({ node, ...props }) => (
                <li className="mb-1" {...props} />
              ),
              strong: ({ node, ...props }) => (
                <strong className="font-semibold" {...props} />
              ),
              em: ({ node, ...props }) => (
                <em className="italic" {...props} />
              ),
              a: ({ node, ...props }) => (
                <a className="text-teal-600 underline hover:text-teal-800" target="_blank" rel="noopener noreferrer" {...props} />
              ),
              blockquote: ({ node, ...props }) => (
                <blockquote className="border-l-4 border-gray-300 pl-4 italic text-gray-600 my-4 bg-gray-50 py-2" {...props} />
              ),
              hr: () => <hr className="my-8 border-gray-200" />,
            }}
          >
            {blog.content}
          </ReactMarkdown>
        </article>
        {/* Extended author box */}
        <div className="max-w-3xl mx-auto px-4 pb-16">
          <div className="flex items-center gap-4 bg-gray-50 rounded-xl p-6 mt-12 shadow">
            <img
              src={blog.author_avatar}
              alt={blog.author}
              className="w-16 h-16 rounded-full object-cover border border-gray-200"
            />
            <div>
              <div className="font-semibold text-gray-900">{blog.author}</div>
              <div className="text-gray-600 text-sm mb-2">{blog.author_bio}</div>
              {/* No author slug or link */}
            </div>
          </div>
        </div>
        {/* Back to blogs button */}
        <div className="max-w-3xl mx-auto px-4">
          <button
            onClick={() => navigate("/blogs")}
            className="mt-8 mb-8 px-5 py-2 bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium rounded-full transition-colors duration-200 flex items-center gap-2 shadow-sm"
          >
            ← Back to Blogs
          </button>
        </div>
      </section>
    </>
  );
};

export default BlogPost;
