// src/components/ScrollToHash.jsx
import { useEffect } from "react";
import { useLocation } from "react-router-dom";

function getOffset() {
  // Match your fixed navbar height
  return window.innerWidth >= 768 ? 96 : 80;
}

export default function ScrollToHash() {
  const { hash } = useLocation();

  useEffect(() => {
    if (!hash) return;

    // Try immediately, then retry a few times in case content isn't mounted yet
    let tries = 0;
    const maxTries = 10;
    const step = () => {
      const el = document.querySelector(hash);
      if (el) {
        const y = el.getBoundingClientRect().top + window.scrollY - getOffset();
        window.scrollTo({ top: y, behavior: "smooth" });
      } else if (tries < maxTries) {
        tries += 1;
        requestAnimationFrame(step);
      }
    };
    step();
  }, [hash]);

  // Also handle first load with hash (hard refresh)
  useEffect(() => {
    if (!window.location.hash) return;
    let tries = 0;
    const maxTries = 10;
    const step = () => {
      const el = document.querySelector(window.location.hash);
      if (el) {
        const y = el.getBoundingClientRect().top + window.scrollY - getOffset();
        window.scrollTo({ top: y, behavior: "smooth" });
      } else if (tries < maxTries) {
        tries += 1;
        requestAnimationFrame(step);
      }
    };
    step();
  }, []);

  return null;
}
